parameters.jsCode:
const intencion = $('Parsear clasificación GPT')
  .first()
  .json
  .intencion
  .trim()
  .toUpperCase();

const encontrados = $input.all().filter(item => {
  const categoria = String(item.json.fields?.['Categoría'] || '')
    .trim()
    .toUpperCase();

  const activo = item.json.fields?.Activo === true;

  return categoria === intencion && activo;
});

return encontrados;

const raw = $json.output[0].content[0].text;

const resultado = JSON.parse(raw);

return [
  {
    json: {
      intencion: resultado.intencion,
      confianza: resultado.confianza,
      requiere_humano: resultado.requiere_humano,
      tema_conocimiento: resultado.tema_conocimiento
    }
  }
];

